   196  static void print_ascii(const u8 * buf, size_t buflen)
   197  {
   198          for (; 0 < buflen; buflen--, buf++) {
   199                  if (isprint(*buf))
   200                          printf("%c", *buf);
   201                  else
   202                          putchar('.');
   203          }
   204  }
