   217  static void sc_asn1_print_integer(const u8 * buf, size_t buflen)
   218  {
   219          size_t a = 0;
   220
   221          if (buflen > sizeof(a)) {
   222                  printf("0x%s", sc_dump_hex(buf, buflen));
   223          } else {
   224                  size_t i;
   225                  for (i = 0; i < buflen; i++) {
   226                          a <<= 8;
   227                          a |= buf[i];
   228                  }
   229                  printf("%"SC_FORMAT_LEN_SIZE_T"u", a);
   230          }
   231  }
